/* =====================================================
   FOOTER SOCIAL STRIP
   ===================================================== */
.footer-inner {
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}
.footer-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-socials {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.footer-social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
